import React, { useState } from "react";
import { Input, Radio, Space } from "antd";
const PayoutOptionsRadio = () => {
  const [value, setValue] = useState(1);
  const onChange = (e) => {
    console.log("radio checked", e.target.value);
    setValue(e.target.value);
  };
  return (
    <Radio.Group onChange={onChange} value={value} className="bg-white w-full">
      <Space direction="vertical" className="w-full">
        <Radio value={1} className="w-full">
          <div className="shadow-sm rounded-sm border-2 w-full min-w-28">
            <p className="w-full text-lg">Mpesa Number</p>
          </div>
        </Radio>
        <Radio value={2}>
          <div>
            <p>Airtel Money</p>
          </div>
        </Radio>
        <Radio value={3}>
          <div>
            <p>Mpesa Paybill</p>
          </div>
        </Radio>
        <Radio value={4}>
          <div>
            <p>Mpesa Till</p>
          </div>
        </Radio>
        <Radio value={5}>
          <div>
            <p>Bank</p>
          </div>
        </Radio>
      </Space>
    </Radio.Group>
  );
};
export default PayoutOptionsRadio;
