import { Button } from "@heroui/react";
import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
} from "../../../../components";
import { useFormik } from "formik";
import useApi from "../../../../hooks/useApi";
import paymentsApi from "../../../../api/paymentsApi";
import { toast, ToastContainer } from "react-toastify";

export default function AirtelPayoutForm() {
  const [errors, setErrors] = useState([]);

  const payoutsApi = useApi(paymentsApi.adminPaymentsAction);

  const processPayoutToAirtel = async (data) => {
    await payoutsApi.request(data);
  };

  useEffect(() => {
    if (payoutsApi.data) {
      if (payoutsApi.data.errors && payoutsApi.data.errors.length) {
        setErrors(payoutsApi.data.errors);
      } else {
        toast.success(payoutsApi.data.response_message);
        formik.resetForm();
      }
    }
    console.log("payoutsAppi.data", payoutsApi.data);
  }, [payoutsApi.data]);
  const formik = useFormik({
    initialValues: {
      amount: "",
      account_number: "",
      narration: "",
      pin: "",
    },

    validationSchema: Yup.object({
      account_number: Yup.string()
        .min(10, "Must be 15 characters or more")
        .required("Airtel number is required"),
      amount: Yup.number().required().min(1).label("Amount"),
      pin: Yup.string().required().min(4).max(4).label("Pin"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      const data = {
        action: "UserAccountToAirtel",
        account_number: values.account_number,
        amount: values.amount,
        narration: values.narration,
        pin: values.pin,
      };
      processPayoutToAirtel(data);

      // resetForm();
    },
  });
  return (
    <div className="mx-10 flex  flex-col items-center justify-center">
      <p className="text-2xl font-bold text-red-500">Airtel Money Payout</p>
      <ToastContainer position="bottom-center" theme="colored" />

      {errors ? (
        <div>
          {errors.map((error) => {
            return (
              <p className="text-lg text-red-500 font-semibold">{error}</p>
            );
          })}
        </div>
      ) : (
        <div></div>
      )}
      <CustomForm
        layout="vertical"
        handleFinish={formik.handleSubmit}
        className=" flex flex-col justify-center items-center w-full my-7"
      >
        <CustomFormItem
          touched={formik.touched.account_number}
          error={formik.errors.account_number}
        >
          <CustomInput
            required={true}
            label="Enter Airtel Number"
            id="account_number"
            name="account_number"
            onChange={formik.handleChange}
            placeholder="Enter Airtel Number"
            size="large"
            type="text"
            value={formik.values.account_number}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.amount}
          error={formik.errors.amount}
        >
          <CustomInput
            required={true}
            label="Enter  Amount"
            id="amount"
            name="amount"
            onChange={formik.handleChange}
            placeholder="Enter Amount"
            size="large"
            type="number"
            value={formik.values.amount}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.narration}
          error={formik.errors.narration}
        >
          <CustomInput
            required={true}
            label="Enter short narration"
            id="narration"
            name="narration"
            onChange={formik.handleChange}
            placeholder="Enter short narration"
            size="large"
            type="text"
            value={formik.values.narration}
          />
        </CustomFormItem>

        <CustomFormItem touched={formik.touched.pin} error={formik.errors.pin}>
          <CustomInput
            required={true}
            label="Enter wallet pin"
            id="pin"
            name="pin"
            onChange={formik.handleChange}
            placeholder="Enter wallet pin"
            size="large"
            type="password"
            value={formik.values.pin}
          />
        </CustomFormItem>

        <div className="w-full flex flex-col items-center  justify-center mt-2">
          <Button
            className="w-36 rounded-md self-center"
            color="danger"
            type="submit"
          >
            Submit
          </Button>
        </div>
      </CustomForm>
    </div>
  );
}
