import React, { useEffect, useRef, useState } from "react";
import PayoutOptionsRadio from "./PayoutOptionsRadio";
import { Avatar, Card, CardBody, RadioGroup } from "@heroui/react";
import { CustomRadioItem } from "../../../components";
import useApi from "../../../hooks/useApi";
import paymentsApi from "../../../api/paymentsApi";
import { Typography } from "antd";
import { usePageVisibility } from "../../../hooks/userPageVisibility";
import AirtelPayoutForm from "./forms/AirtelPayoutForm";
import MpesaPayoutForm from "./forms/MpesaPayoutForm";
import BankPayoutForm from "./forms/BankPayoutForm";
import PaybillPayoutForm from "./forms/PaybillPayoutForm";
import TillPayoutForm from "./forms/TillPayoutForm";
import { toast, ToastContainer } from "react-toastify";
import { useStateContext } from "../../../contexts/ContextProvider";
const { Text, Link } = Typography;

export default function CollectionAccounts() {
  const [data, setdata] = useState();
  const { currentColor } = useStateContext();
  const paymentMethods = [
    {
      id: "1",
      title: "Airtel Phone",
      description: "Payout to Airtel phone number",
    },
    {
      id: "2",
      title: "Bank Account",
      description: "Payout to Bank account",
    },
    {
      id: "3",
      title: "Mpesa Phone",
      description: "Payout to Mpesa phone number",
    },
    {
      id: "4",
      title: "Mpesa Paybill",
      description: "Payout to Mpesa paybill",
    },
    {
      id: "5",
      title: "Mpesa Till",
      description: "Payout to Mpesa till",
    },
  ];
  const [selectedPayoutMethod, setselectedPayoutMethod] = useState();

  const handleSelectPaymentOption = (e) => {
    const payment_method = paymentMethods.find((x) => x.id === e.target.value);
    if (payment_method) {
      setselectedPayoutMethod(payment_method);
    }
  };

  const collectionAccountStatusApi = useApi(paymentsApi.adminPaymentsAction);

  const getAccountStatus = async () => {
    collectionAccountStatusApi.request({
      action: "GetEntityCollectionAccountData",
    });
  };

  useEffect(() => {
    getAccountStatus();
  }, []);

  useEffect(() => {
    if (
      collectionAccountStatusApi.data &&
      collectionAccountStatusApi.data.data
    ) {
      setdata(collectionAccountStatusApi.data.data);
    }
    console.log(
      "collectionAccountStatusApi.data",
      collectionAccountStatusApi.data
    );
  }, [collectionAccountStatusApi.data]);

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      getAccountStatus();
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 20000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled, getAccountStatus]);

  return data ? (
    <div className="flex flex-row p-2">
      <ToastContainer position="bottom-center" theme="colored" />
      <div className="w-1/3">
        <div
          style={{
            backgroundColor: currentColor,
            marginBottom: 10,
            marginTop: 10,
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <p className="text-white text-center text-2xl font-bold">
            {data.acccount_details.account_name}
          </p>
          <p className="text-white text-center text-xl font-bold">
            {data.acccount_details.account_phone}
          </p>
        </div>

        <div
          className="flex flex-col items-center justify-center"
          style={{
            backgroundColor: currentColor,
            marginBottom: 10,
            marginTop: 10,
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <p className="text-white font-bold">Account No:</p>
          <p className="text-white font-bold text-2xl">
            {data.acccount_details.account_number}
          </p>
        </div>
        <div
          className="flex flex-col items-center justify-center"
          style={{
            backgroundColor: currentColor,
            marginBottom: 10,
            marginTop: 10,
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <p className="text-white font-bold">Balance:</p>
          <p className="text-white font-bold text-2xl">
            KES {data.acccount_details.current_balance}
          </p>
        </div>
      </div>

      <div className="w-1/3 bg-gray-100">
        <Card className="max-w-full mx-1 md:mx-5 my-2">
          <CardBody>
            <RadioGroup
              description="Payout options for funds in your account"
              defaultValue={selectedPayoutMethod}
              onChange={(e) => handleSelectPaymentOption(e)}
              orientation="vertical"
              label="Payout Options"
            >
              {paymentMethods && paymentMethods.length ? (
                paymentMethods.map((x) => (
                  <CustomRadioItem description={x.description} value={x.id}>
                    <Avatar
                      name={x.title}
                      src={x.images && x.images.length ? x.images[0].image : ""}
                    />
                    {x.title}
                  </CustomRadioItem>
                ))
              ) : (
                <p></p>
              )}
            </RadioGroup>
          </CardBody>
        </Card>
      </div>
      {selectedPayoutMethod ? (
        <div className="w-1/3">
          {selectedPayoutMethod.title === "Airtel Phone" && (
            <AirtelPayoutForm />
          )}
          {selectedPayoutMethod.title === "Bank Account" && <BankPayoutForm />}
          {selectedPayoutMethod.title === "Mpesa Phone" && <MpesaPayoutForm />}
          {selectedPayoutMethod.title === "Mpesa Paybill" && (
            <PaybillPayoutForm />
          )}
          {selectedPayoutMethod.title === "Mpesa Till" && <TillPayoutForm />}
        </div>
      ) : (
        <div></div>
      )}
    </div>
  ) : (
    <div>
      <p>No data</p>
    </div>
  );
}
